const corsHeaders = {
    "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
        "Access-Control-Allow-Headers": "Authorization,Content-Type",
          "Content-Type": "application/json; charset=utf-8",
          };
        

          const json = (data, status = 200) => new Response(JSON.stringify(data), { status, headers: corsHeaders });
          const err = (message, status = 400) => json({ error: message }, status);
          const enc = (s) => btoa(String.fromCharCode(...new TextEncoder().encode(s))).replace(/=/g, "").replace(/\+/g, "-").replace(/\//g, "_");
          const b64url = (bytes) => {
            let binary = "";
              for (const b of new Uint8Array(bytes)) binary += String.fromCharCode(b);
                return btoa(binary).replace(/=/g, "").replace(/\+/g, "-").replace(/\//g, "_");
                };
                const fromB64url = (s) => Uint8Array.from(atob(s.replace(/-/g, "+").replace(/_/g, "/") + "===".slice((s.length + 3) % 4)), c => c.charCodeAt(0));

                function decodeValue(v) {
                  if (!v || typeof v !== "object") return null;
                    if ("nullValue" in v) return null;
                      if ("stringValue" in v) return v.stringValue;
                        if ("booleanValue" in v) return v.booleanValue;
                          if ("integerValue" in v) return Number(v.integerValue);
                            if ("doubleValue" in v) return Number(v.doubleValue);
                              if ("timestampValue" in v) return v.timestampValue;
                                if ("referenceValue" in v) return v.referenceValue;
                                  if ("bytesValue" in v) return v.bytesValue;
                                    if ("geoPointValue" in v) return v.geoPointValue;
                                      if ("arrayValue" in v) return (v.arrayValue.values || []).map(decodeValue);
                                        if ("mapValue" in v) return decodeFields(v.mapValue.fields || {});
                                          return null;
                                          }
                                          function decodeFields(fields = {}) {
                                            return Object.fromEntries(Object.entries(fields).map(([k,v]) => [k, decodeValue(v)]));
                                            }
                                            function encodeValue(v) {
                                              if (v === null || v === undefined) return { nullValue: null };
                                                if (typeof v === "string") {
                                                    if (/^\d{4}-\d\d-\d\dT/.test(v)) return { timestampValue: v };
                                                        return { stringValue: v };
                                                          }
                                                            if (typeof v === "boolean") return { booleanValue: v };
                                                              if (typeof v === "number") return Number.isInteger(v) ? { integerValue: String(v) } : { doubleValue: v };
                                                                if (Array.isArray(v)) return { arrayValue: { values: v.map(encodeValue) } };
                                                                  if (typeof v === "object") return { mapValue: { fields: encodeFields(v) } };
                                                                    return { stringValue: String(v) };
                                                                    }
                                                                    function encodeFields(data = {}) {
                                                                      return Object.fromEntries(Object.entries(data).map(([k,v]) => [k, encodeValue(v)]));
                                                                      }
                                                                      function safeText(value, max = 500) {
                                                                        return String(value ?? "").trim().slice(0, max);
                                                                        }
                                                                        function assert(condition, message, status = 400) {
                                                                          if (!condition) throw Object.assign(new Error(message), { status });
                                                                          }

                                                                          async function firebaseIdentity(idToken, env) {
                                                                            const response = await fetch(`https://identitytoolkit.googleapis.com/v1/accounts:lookup?key=${env.FIREBASE_API_KEY}`, {
                                                                                method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ idToken })
                                                                                  });
                                                                                    if (!response.ok) throw Object.assign(new Error("جلسة Firebase غير صالحة أو منتهية. أعد تسجيل الدخول."), { status: 401 });
                                                                                      const data = await response.json();
                                                                                        const user = data.users && data.users[0];
                                                                                          if (!user || !user.localId) throw Object.assign(new Error("تعذر التحقق من هوية المستخدم."), { status: 401 });
                                                                                            return { uid: user.localId, email: user.email || "" };
                                                                                            }

                                                                                            async function googleAccessToken(env) {
                                                                                              const email = env.SERVICE_ACCOUNT_EMAIL;
                                                                                                const pem = env.SERVICE_ACCOUNT_PRIVATE_KEY.replace(/\\n/g, "\n");
                                                                                                  const keyData = pem.replace(/-----BEGIN PRIVATE KEY-----|-----END PRIVATE KEY-----|\s/g, "");
                                                                                                    const binary = Uint8Array.from(atob(keyData), c => c.charCodeAt(0));
                                                                                                      const key = await crypto.subtle.importKey("pkcs8", binary, { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" }, false, ["sign"]);
                                                                                                        const now = Math.floor(Date.now() / 1000);
                                                                                                          const header = enc(JSON.stringify({ alg: "RS256", typ: "JWT" }));
                                                                                                            const claim = enc(JSON.stringify({
                                                                                                                iss: email, scope: "https://www.googleapis.com/auth/datastore",
                                                                                                                    aud: "https://oauth2.googleapis.com/token", iat: now, exp: now + 3500
                                                                                                                      }));
                                                                                                                        const unsigned = `${header}.${claim}`;
                                                                                                                          const signature = await crypto.subtle.sign("RSASSA-PKCS1-v1_5", key, new TextEncoder().encode(unsigned));
                                                                                                                            const assertion = `${unsigned}.${b64url(signature)}`;
                                                                                                                              const response = await fetch("https://oauth2.googleapis.com/token", {
                                                                                                                                  method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" },
                                                                                                                                      body: new URLSearchParams({ grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer", assertion })
                                                                                                                                        });
                                                                                                                                          const data = await response.json();
                                                                                                                                            if (!response.ok || !data.access_token) throw new Error("تعذر مصادقة خادم Firestore. راجع أسرار Worker وصلاحيات حساب الخدمة.");
                                                                                                                                              return data.access_token;
                                                                                                                                              }

                                                                                                                                              class Firestore {
                                                                                                                                                constructor(env, token) {
                                                                                                                                                    this.project = env.FIREBASE_PROJECT_ID;
                                                                                                                                                        this.token = token;
                                                                                                                                                            this.base = `https://firestore.googleapis.com/v1/projects/${this.project}/databases/(default)/documents`;
                                                                                                                                                              }
                                                                                                                                                                /** @returns {Promise<any>} */
                                                                                                                                                                  async request(path, body, method = "POST") {
                                                                                                                                                                      const r = await fetch(`${this.base}${path}`, {
                                                                                                                                                                            method,
                                                                                                                                                                                  headers: { Authorization: `Bearer ${this.token}`, "Content-Type": "application/json" },
                                                                                                                                                                                        ...(body === undefined ? {} : { body: JSON.stringify(body) })
                                                                                                                                                                                            });
                                                                                                                                                                                                const raw = await r.text();
                                                                                                                                                                                                    if (!r.ok) {
                                                                                                                                                                                                          let errorData = {};
                                                                                                                                                                                                                try { errorData = raw ? JSON.parse(raw) : {}; } catch {}
                                                                                                                                                                                                                      throw Object.assign(new Error(errorData.error?.message || `Firestore API error ${r.status}`), { status: r.status });
                                                                                                                                                                                                                          }
                                                                                                                                                                                                                              // Firestore batchGet returns newline-delimited JSON objects, not one JSON array.
                                                                                                                                                                                                                                  if (path === ":batchGet") {
                                                                                                                                                                                                                                        return raw.split(/\r?\n/).filter(line => line.trim()).map(line => JSON.parse(line));
                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                if (!raw.trim()) return {};
                                                                                                                                                                                                                                                    return JSON.parse(raw);
                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                        name(path) { return `${this.base}/${path}`; }
                                                                                                                                                                                                                                                          async get(path) {
                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                    const d = await this.request(`/${path}`, undefined, "GET");
                                                                                                                                                                                                                                                                          return { exists: true, name: d.name, updateTime: d.updateTime, data: decodeFields(d.fields || {}) };
                                                                                                                                                                                                                                                                              } catch (e) {
                                                                                                                                                                                                                                                                                    if (e.status === 404) return { exists: false, data: {} };
                                                                                                                                                                                                                                                                                          throw e;
                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                  async begin() {
                                                                                                                                                                                                                                                                                                      const d = await this.request(":beginTransaction", { options: { readWrite: {} } });
                                                                                                                                                                                                                                                                                                          return d.transaction;
                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                              async batchGet(paths, tx) {
                                                                                                                                                                                                                                                                                                                  const d = await this.request(":batchGet", { documents: paths.map(p => this.name(p)), transaction: tx });
                                                                                                                                                                                                                                                                                                                      const result = {};
                                                                                                                                                                                                                                                                                                                          for (const item of d) {
                                                                                                                                                                                                                                                                                                                                if (item.found) {
                                                                                                                                                                                                                                                                                                                                        const path = item.found.name.split("/documents/")[1];
                                                                                                                                                                                                                                                                                                                                                result[path] = { exists: true, name: item.found.name, updateTime: item.found.updateTime, data: decodeFields(item.found.fields || {}) };
                                                                                                                                                                                                                                                                                                                                                      } else if (item.missing) {
                                                                                                                                                                                                                                                                                                                                                              const path = item.missing.split("/documents/")[1];
                                                                                                                                                                                                                                                                                                                                                                      result[path] = { exists: false, data: {} };
                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                    return result;
                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                        async commit(tx, writes) {
                                                                                                                                                                                                                                                                                                                                                                                            return this.request(":commit", { transaction: tx, writes });
                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                updateWrite(path, data, updateTime) {
                                                                                                                                                                                                                                                                                                                                                                                                    return { update: { name: this.name(path), fields: encodeFields(data) }, currentDocument: { updateTime } };
                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                        createWrite(path, data) {
                                                                                                                                                                                                                                                                                                                                                                                                            return { update: { name: this.name(path), fields: encodeFields(data) }, currentDocument: { exists: false } };
                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                              async function getActor(request, env, fs, identity) {
                                                                                                                                                                                                                                                                                                                                                                                                                if (!identity) {
                                                                                                                                                                                                                                                                                                                                                                                                                    const auth = request.headers.get("Authorization") || "";
                                                                                                                                                                                                                                                                                                                                                                                                                        const match = auth.match(/^Bearer\s+(.+)$/i);
                                                                                                                                                                                                                                                                                                                                                                                                                            assert(match, "يجب تسجيل الدخول أولًا.", 401);
                                                                                                                                                                                                                                                                                                                                                                                                                                identity = await firebaseIdentity(match[1], env);
                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                    const profile = await fs.get(`users/${identity.uid}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                      assert(profile.exists, "ملف المستخدم غير موجود.", 403);
                                                                                                                                                                                                                                                                                                                                                                                                                                        assert(profile.data.disabled === false, "الحساب معطل أو حالة الحساب غير محددة.", 403);
                                                                                                                                                                                                                                                                                                                                                                                                                                          return { ...identity, ...profile.data, uid: identity.uid };
                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                          function requireRole(actor, roles) {
                                                                                                                                                                                                                                                                                                                                                                                                                                            assert(roles.includes(actor.role), "ليس لديك صلاحية لتنفيذ هذه العملية.", 403);
                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                            function isoNow() { return new Date().toISOString(); }

                                                                                                                                                                                                                                                                                                                                                                                                                                            async function transact(env, fs, paths, handler) {
                                                                                                                                                                                                                                                                                                                                                                                                                                              const tx = await fs.begin();
                                                                                                                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                    const docs = await fs.batchGet(paths, tx);
                                                                                                                                                                                                                                                                                                                                                                                                                                                        const writes = await handler(docs);
                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!writes || !writes.length) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  await fs.commit(tx, []);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return { ok: true };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await fs.commit(tx, writes);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return { ok: true };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // Firestore transaction is aborted by not committing; errors are returned to caller.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              throw e;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                async function submitCustomerOrder(env, fs, actor, body) {
  requireRole(actor, ["CUSTOMER"]);
  const deliveryAddress = safeText(body.deliveryAddress, 500);
  const notes = safeText(body.notes, 1000);
  assert(deliveryAddress, "يرجى إدخال عنوان التوصيل.");
  assert(Array.isArray(body.items) && body.items.length > 0 && body.items.length <= 100, "سلة الطلب غير صالحة.");

  // لا نعتمد السعر أو الاسم أو الإجمالي المرسل من هاتف العميل.
  const quantities = new Map();
  for (const item of body.items) {
    const productId = safeText(item.productId || item.id, 180);
    const quantity = Number(item.quantity ?? item.qty);
    assert(productId && !productId.includes("/"), "يوجد منتج غير صالح في السلة.");
    assert(Number.isSafeInteger(quantity) && quantity > 0, "كمية أحد المنتجات غير صالحة.");
    quantities.set(productId, (quantities.get(productId) || 0) + quantity);
  }
  assert(quantities.size > 0 && quantities.size <= 100, "عدد المنتجات غير صالح.");

  const orderId = crypto.randomUUID();
  const orderPath = `orders/${orderId}`;
  const productPaths = [...quantities.keys()].map(id => `products/${id}`);
  const paths = [orderPath, ...productPaths];
  const result = await transact(env, fs, paths, async docs => {
    assert(!docs[orderPath]?.exists, "تعذر إنشاء رقم طلب فريد. حاول مرة أخرى.", 409);
    const items = [];
    const writes = [];
    let totalAmount = 0;
    for (const [productId, quantity] of quantities.entries()) {
      const path = `products/${productId}`;
      const snapshot = docs[path];
      assert(snapshot?.exists, `المنتج ${productId} غير موجود.`, 404);
      const product = snapshot.data;
      assert(product.active !== false && product.disabled !== true, `المنتج ${safeText(product.name || productId, 100)} غير متاح حاليًا.`, 409);
      const stock = Number(product.quantity ?? 0);
      const reserved = Number(product.reservedQuantity ?? 0);
      const available = stock - reserved;
      assert(Number.isFinite(stock) && Number.isFinite(reserved) && stock >= 0 && reserved >= 0 && reserved <= stock, `بيانات مخزون المنتج ${safeText(product.name || productId, 100)} غير سليمة.`, 409);
      assert(quantity <= available, `الكمية المتاحة من ${safeText(product.name || productId, 100)} لا تكفي. المتاح: ${available}.`, 409);
      const sellingPrice = Number(product.sellingPrice ?? product.price);
      const discount = Number(product.discount ?? 0);
      const unitPrice = Number(product.finalPrice !== undefined ? product.finalPrice : (sellingPrice - discount));
      assert(Number.isFinite(sellingPrice) && sellingPrice >= 0 && Number.isFinite(discount) && discount >= 0 &&
        Number.isFinite(unitPrice) && unitPrice >= 0 && unitPrice <= sellingPrice,
        `سعر المنتج أو خصمه غير مضبوط: ${safeText(product.name || productId, 100)}.`, 409);
      const lineTotal = Math.round((unitPrice * quantity + Number.EPSILON) * 100) / 100;
      totalAmount += lineTotal;
      items.push({ productId, productName: safeText(product.name || product.productName || productId, 180), unitPrice, discount, quantity, total: lineTotal, subtotal: lineTotal });
      writes.push(fs.updateWrite(path, { ...product, reservedQuantity: reserved + quantity, updatedAt: isoNow() }, snapshot.updateTime));
    }
    totalAmount = Math.round((totalAmount + Number.EPSILON) * 100) / 100;
    const order = {
      customerId: actor.uid,
      pharmacyName: safeText(actor.pharmacyName || actor.name || actor.email || "العميل", 180),
      deliveryAddress,
      notes,
      items,
      totalAmount,
      status: "NEW",
      paymentStatus: "UNPAID",
      paymentMethod: null,
      paymentReference: null,
      deliveryAgentId: null,
      createdAt: isoNow(),
      updatedAt: isoNow(),
      source: "customer_app",
      stockReserved: true
    };
    writes.push(fs.createWrite(orderPath, order));
    return writes;
  });
  return { ...result, orderId, status: "NEW" };
}

async function approveRequest(env, fs, actor, body) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  requireRole(actor, ["ADMIN"]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const requestId = safeText(body.requestId, 180);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      assert(requestId && !requestId.includes("/"), "رقم طلب المراجعة غير صالح.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const reqPath = `orderRequests/${requestId}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const orderPath = `orders/${requestId}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const reqSnap = await fs.get(reqPath);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              assert(reqSnap.exists, "طلب المراجعة غير موجود.", 404);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (reqSnap.data.status === "APPROVED") return { ok: true, orderId: requestId, alreadyApproved: true };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  assert(reqSnap.data.status === "PENDING_REVIEW", "لا يمكن اعتماد هذا الطلب بهذه الحالة.", 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const req = reqSnap.data;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      assert(Array.isArray(req.items) && req.items.length > 0 && req.items.length <= 50, "الأصناف غير صالحة.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const productPaths = [...new Set(req.items.map(i => `products/${safeText(i.productId, 180)}`))];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          assert(productPaths.every(p => !p.endsWith("/")), "يوجد معرّف منتج غير صالح.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const tx = await fs.begin();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const paths = [reqPath, orderPath, `users/${actor.uid}`, `customers/${req.customerId}`, ...productPaths];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const docs = await fs.batchGet(paths, tx);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const currentReq = docs[reqPath];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              assert(currentReq?.exists, "طلب المراجعة غير موجود.", 404);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (currentReq.data.status === "APPROVED" && docs[orderPath]?.exists) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await fs.commit(tx, []);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return { ok: true, orderId: requestId, alreadyApproved: true };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      assert(currentReq.data.status === "PENDING_REVIEW", "تمت معالجة هذا الطلب مسبقًا.", 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          assert(docs[orderPath] && !docs[orderPath].exists, "يوجد طلب رسمي بنفس المعرّف.", 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const customer = docs[`customers/${req.customerId}`]?.data || {};
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const userSnap = docs[`users/${req.customerId}`];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const user = userSnap?.data || {};
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          assert(userSnap?.exists && user.role === "CUSTOMER" && user.disabled === false, "حساب العميل غير نشط أو ملفه غير صالح.", 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              assert(currentReq.data.customerId && currentReq.data.customerEmail, "بيانات العميل في طلب المراجعة غير مكتملة.", 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  let total = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const orderItems = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const productUpdates = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const requested = new Map();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  for (const item of req.items) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const productId = safeText(item.productId, 180);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const qty = Number(item.quantity);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    assert(productId && Number.isInteger(qty) && qty > 0 && qty <= 999, "كمية أو منتج غير صالح.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          requested.set(productId, (requested.get(productId) || 0) + qty);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  for (const [productId, qty] of requested) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const path = `products/${productId}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const snap = docs[path];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    assert(snap?.exists, `المنتج ${productId} غير موجود.`, 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const p = snap.data;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                assert(p.status !== "DISABLED" && p.disabled !== true, `المنتج ${p.name || productId} غير نشط.`, 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const onHand = Number(p.quantity ?? 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const reserved = Number(p.reservedQuantity ?? 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  assert(Number.isFinite(onHand) && Number.isFinite(reserved) && onHand >= 0 && reserved >= 0, `مخزون المنتج ${p.name || productId} غير مضبوط.`, 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        assert(onHand - reserved >= qty, `المخزون المتاح غير كافٍ للمنتج ${p.name || productId}.`, 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const unitPrice = Number(p.finalPrice !== undefined ? p.finalPrice : (Number(p.sellingPrice ?? p.price ?? 0) - Number(p.discount ?? 0)));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    assert(Number.isFinite(unitPrice) && unitPrice >= 0, `سعر المنتج ${p.name || productId} غير صالح.`, 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const lineTotal = Math.round(unitPrice * qty * 100) / 100;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                total += lineTotal;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      orderItems.push({ productId, productName: safeText(p.name || productId, 200), quantity: qty, unitPrice, discount: Number(p.discount || 0), subtotal: lineTotal, total: lineTotal });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const updated = { ...p, reservedQuantity: reserved + qty, updatedAt: isoNow() };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  productUpdates.push(fs.updateWrite(path, updated, snap.updateTime));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          total = Math.round(total * 100) / 100;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const order = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    customerId: req.customerId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          customerEmail: req.customerEmail || "",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                customerName: safeText(customer.managerName || user.name || req.customerEmail || "عميل", 160),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      pharmacyName: safeText(customer.pharmacyName || "", 160),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            phone: safeText(customer.phone || "", 40),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  deliveryAddress: safeText(req.deliveryAddress, 500),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        notes: safeText(req.notes, 1000),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              items: orderItems,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    totalAmount: total,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          currency: "YER",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                status: "NEW",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      paymentStatus: "UNPAID",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            paymentMethod: null,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  paymentReference: null,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        deliveryAgentId: null,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              createdAt: isoNow(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    approvedAt: isoNow(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          approvedBy: actor.uid,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                sourceRequestId: requestId
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const updatedReq = { ...currentReq.data, status: "APPROVED", officialOrderId: requestId, reviewedAt: isoNow(), reviewedBy: actor.uid };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const reservationLogs = [...requested.entries()].map(([productId, qty]) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  fs.createWrite(`inventoryLogs/${requestId}_${productId}_RESERVE`, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          orderId: requestId, productId, quantityChange: 0, reservedChange: qty,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  reason: "ORDER_APPROVED_RESERVATION", actorId: actor.uid, createdAt: isoNow()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const writes = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ...productUpdates,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ...reservationLogs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  fs.createWrite(orderPath, order),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fs.updateWrite(reqPath, updatedReq, currentReq.updateTime)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await fs.commit(tx, writes);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return { ok: true, orderId: requestId, totalAmount: total };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          throw e;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            async function rejectRequest(env, fs, actor, body) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              requireRole(actor, ["ADMIN"]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const id = safeText(body.requestId, 180);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  assert(id && !id.includes("/"), "رقم طلب المراجعة غير صالح.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const tx = await fs.begin();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const paths = [`orderRequests/${id}`];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const docs = await fs.batchGet(paths, tx);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const s = docs[paths[0]];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            assert(s?.exists, "طلب المراجعة غير موجود.", 404);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              assert(s.data.status === "PENDING_REVIEW", "لا يمكن رفض الطلب بهذه الحالة.", 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await fs.commit(tx, [fs.updateWrite(paths[0], { ...s.data, status: "REJECTED", rejectionReason: safeText(body.reason || "لم يذكر سبب", 500), reviewedAt: isoNow(), reviewedBy: actor.uid }, s.updateTime)]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return { ok: true };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const ALLOWED_TRANSITIONS = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    NEW: ["PREPARING"],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      PREPARING: ["READY_FOR_DELIVERY"],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        READY_FOR_DELIVERY: [],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ASSIGNED_TO_DELIVERY: ["OUT_FOR_DELIVERY"],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            OUT_FOR_DELIVERY: [],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              DELIVERED: ["COMPLETED"],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                COMPLETED: [],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  CANCELLED: []
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  async function changeStatus(env, fs, actor, body) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const id = safeText(body.orderId, 180), next = safeText(body.nextStatus, 60);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      assert(id && !id.includes("/"), "رقم الطلب غير صالح.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const tx = await fs.begin();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const path = `orders/${id}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const docs = await fs.batchGet([path], tx);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const s = docs[path];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                assert(s?.exists, "الطلب الرسمي غير موجود.", 404);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const o = s.data;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (actor.role === "DELIVERY") assert(o.deliveryAgentId === actor.uid, "هذا الطلب غير مسند إليك.", 403);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (["PREPARING", "READY_FOR_DELIVERY"].includes(next)) requireRole(actor, ["ADMIN", "WAREHOUSE"]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else if (next === "OUT_FOR_DELIVERY") requireRole(actor, ["ADMIN", "DELIVERY"]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          else if (next === "COMPLETED") requireRole(actor, ["ADMIN"]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            else if (next === "CANCELLED") requireRole(actor, ["ADMIN"]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              else throw Object.assign(new Error("حالة الطلب المطلوبة غير مدعومة."), { status: 400 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                assert((ALLOWED_TRANSITIONS[o.status] || []).includes(next), `لا يمكن نقل الطلب من ${o.status} إلى ${next}.`, 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const updated = { ...o, status: next, updatedAt: isoNow(), statusUpdatedBy: actor.uid };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    await fs.commit(tx, [fs.updateWrite(path, updated, s.updateTime)]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return { ok: true, status: next };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      async function assignDelivery(env, fs, actor, body) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        requireRole(actor, ["ADMIN"]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const id = safeText(body.orderId, 180), agentId = safeText(body.deliveryAgentId, 180);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            assert(id && agentId && !id.includes("/") && !agentId.includes("/"), "رقم الطلب أو المندوب غير صالح.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const tx = await fs.begin();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const orderPath = `orders/${id}`, userPath = `users/${agentId}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const docs = await fs.batchGet([orderPath, userPath], tx);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const o = docs[orderPath], agent = docs[userPath];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      assert(o?.exists, "الطلب الرسمي غير موجود.", 404);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        assert(agent?.exists && agent.data.role === "DELIVERY" && agent.data.disabled === false, "المندوب غير موجود أو غير نشط.", 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          assert(o.data.status === "READY_FOR_DELIVERY", "يجب تجهيز الطلب قبل تعيين المندوب.", 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const updated = { ...o.data, deliveryAgentId: agentId, deliveryAgentName: safeText(agent.data.name || "", 160), status: "ASSIGNED_TO_DELIVERY", assignedAt: isoNow(), assignedBy: actor.uid, updatedAt: isoNow() };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await fs.commit(tx, [fs.updateWrite(orderPath, updated, o.updateTime)]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return { ok: true };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                async function fulfill(env, fs, actor, body) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const id = safeText(body.orderId, 180);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const method = safeText(body.paymentMethod, 40);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const reference = safeText(body.paymentReference, 160);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        assert(id && !id.includes("/"), "رقم الطلب غير صالح.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          assert(["CASH", "WALLET", "BANK_TRANSFER"].includes(method), "طريقة الدفع غير مدعومة.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (method !== "CASH") assert(reference.length >= 3, "أدخل رقم مرجع التحويل أو المحفظة.", 400);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const tx = await fs.begin();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const orderPath = `orders/${id}`, paymentPath = `payments/${id}`, invoicePath = `invoices/${id}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const docs = await fs.batchGet([orderPath, paymentPath, invoicePath], tx);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const s = docs[orderPath];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      assert(s?.exists, "الطلب الرسمي غير موجود.", 404);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const o = s.data;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (actor.role === "DELIVERY") assert(o.deliveryAgentId === actor.uid, "هذا الطلب غير مسند إليك.", 403);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            requireRole(actor, ["ADMIN", "DELIVERY"]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              assert(o.status === "OUT_FOR_DELIVERY", "لا يمكن تسجيل التسليم إلا بعد بدء التوصيل.", 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                assert(!docs[paymentPath]?.exists && !docs[invoicePath]?.exists, "يوجد سجل تحصيل سابق لهذا الطلب؛ أوقف العملية وراجع الإدارة.", 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const total = Number(o.totalAmount);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    assert(Number.isFinite(total) && total >= 0, "إجمالي الطلب غير صالح.", 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const productPaths = [...new Set((o.items || []).map(i => `products/${safeText(i.productId,180)}`))];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const productDocs = await fs.batchGet(productPaths, tx);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const writes = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (const item of o.items || []) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const path = `products/${safeText(item.productId,180)}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const prod = productDocs[path];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const qty = Number(item.quantity);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            assert(prod?.exists && Number.isInteger(qty) && qty > 0, "بيانات مخزون الطلب غير صالحة.", 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const p = prod.data, stock = Number(p.quantity ?? 0), reserved = Number(p.reservedQuantity ?? 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    assert(stock >= qty && reserved >= qty, `حجز المخزون غير متطابق للمنتج ${p.name || item.productId}.`, 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        writes.push(fs.updateWrite(path, { ...p, quantity: stock - qty, reservedQuantity: reserved - qty, updatedAt: isoNow() }, prod.updateTime));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const now = isoNow();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const updatedOrder = { ...o, status: "DELIVERED", paymentStatus: "PAID", paymentMethod: method, paymentReference: reference || null, paidAmount: total, deliveredAt: now, deliveredBy: actor.uid, updatedAt: now };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const payment = { orderId: id, customerId: o.customerId, amount: total, currency: "YER", method, reference: reference || null, status: "PAID", receivedBy: actor.uid, receivedAt: now, createdAt: now };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const invoice = { orderId: id, customerId: o.customerId, customerName: o.customerName || "", pharmacyName: o.pharmacyName || "", items: o.items || [], totalAmount: total, currency: "YER", paymentMethod: method, paymentStatus: "PAID", paymentReference: reference || null, issuedAt: now, issuedBy: actor.uid };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    writes.push(fs.updateWrite(orderPath, updatedOrder, s.updateTime));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      writes.push(fs.createWrite(paymentPath, payment));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        writes.push(fs.createWrite(invoicePath, invoice));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // Immutable audit trail for the stock movement.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (const item of o.items || []) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const logId = `${id}_${safeText(item.productId,80)}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    writes.push(fs.createWrite(`inventoryLogs/${logId}`, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          orderId: id, productId: item.productId, productName: item.productName || "",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                quantityChange: -Number(item.quantity), reservedChange: -Number(item.quantity),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      reason: "ORDER_DELIVERED", actorId: actor.uid, createdAt: now
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await fs.commit(tx, writes);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return { ok: true, paymentStatus: "PAID", amount: total };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                async function cancelOrder(env, fs, actor, body) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  requireRole(actor, ["ADMIN"]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const id = safeText(body.orderId, 180);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      assert(id && !id.includes("/"), "رقم الطلب غير صالح.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const tx = await fs.begin();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const orderPath = `orders/${id}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const initial = await fs.batchGet([orderPath], tx);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const s = initial[orderPath];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                assert(s?.exists, "الطلب الرسمي غير موجود.", 404);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const o = s.data;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    assert(["NEW", "PREPARING", "READY_FOR_DELIVERY", "ASSIGNED_TO_DELIVERY"].includes(o.status), "لا يمكن إلغاء الطلب بعد بدء التوصيل أو بعد التسليم.", 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const productPaths = [...new Set((o.items || []).map(i => `products/${safeText(i.productId,180)}`))];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const products = await fs.batchGet(productPaths, tx);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const writes = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (const item of o.items || []) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const path = `products/${safeText(item.productId,180)}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const sP = products[path];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        assert(sP?.exists, "منتج الطلب غير موجود في المخزون.", 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const p = sP.data, qty = Number(item.quantity), reserved = Number(p.reservedQuantity ?? 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                assert(reserved >= qty, `تعذر تحرير الحجز للمنتج ${p.name || item.productId}. راجع المخزون يدويًا.`, 409);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    writes.push(fs.updateWrite(path, { ...p, reservedQuantity: reserved - qty, updatedAt: isoNow() }, sP.updateTime));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        writes.push(fs.createWrite(`inventoryLogs/${id}_${safeText(item.productId,80)}_CANCEL`, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              orderId: id, productId: item.productId, quantityChange: 0, reservedChange: -qty,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    reason: "ORDER_CANCELLED_RESERVATION_RELEASE", actorId: actor.uid, createdAt: isoNow()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            writes.push(fs.updateWrite(orderPath, { ...o, status: "CANCELLED", cancelledAt: isoNow(), cancelledBy: actor.uid, updatedAt: isoNow() }, s.updateTime));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await fs.commit(tx, writes);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return { ok: true };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                export default {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  async fetch(request, env) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: corsHeaders });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const url = new URL(request.url);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (request.method === "GET" && url.pathname === "/health") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return json({ ok: true, service: "hilal-pharma-order-api", mode: "configured", project: env.FIREBASE_PROJECT_ID || null });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (request.method === "GET" && (url.pathname === "/" || url.pathname === "/health")) return json({ ok: true, service: "hilal-pharma-order-api", mode: "configured", project: env.FIREBASE_PROJECT_ID || "not-configured" }); if (request.method !== "POST" || !url.pathname.startsWith("/api/")) return err("المسار غير موجود.", 404);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      assert(env.FIREBASE_PROJECT_ID && env.FIREBASE_API_KEY && env.SERVICE_ACCOUNT_EMAIL && env.SERVICE_ACCOUNT_PRIVATE_KEY, "إعدادات Worker غير مكتملة.", 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const body = await request.json().catch(() => ({}));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const auth = request.headers.get("Authorization") || "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const match = auth.match(/^Bearer\s+(.+)$/i);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              assert(match, "يجب تسجيل الدخول أولًا.", 401);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const identity = await firebaseIdentity(match[1], env);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const accessToken = await googleAccessToken(env);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const fs = new Firestore(env, accessToken);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const actor = await getActor(request, env, fs, identity);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let result;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  switch (url.pathname) { case "/api/orders/submit": result = await submitCustomerOrder(env, fs, actor, body); break; case "/api/order-requests/approve": result = await approveRequest(env, fs, actor, body); break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case "/api/order-requests/reject": result = await rejectRequest(env, fs, actor, body); break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          case "/api/orders/status": result = await changeStatus(env, fs, actor, body); break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case "/api/orders/assign-delivery": result = await assignDelivery(env, fs, actor, body); break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          case "/api/orders/fulfill": result = await fulfill(env, fs, actor, body); break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case "/api/orders/cancel": result = await cancelOrder(env, fs, actor, body); break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          default: return err("المسار غير موجود.", 404);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return json(result);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } catch (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const status = e.status || 500;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return err(e.message || "حدث خطأ غير متوقع.", status);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };
      
                                                                                                                                                                                                                                                                                                                                                                                      
